VALUES ('chikkamagaluru', 'Chikkamagaluru', 'chikkamagaluru', 'ಚಿಕ್ಕಮಗಳೂರು', 'Malnad', 'Malnad', 'Land of Coffee & Highest Peaks', 'Home to Karnataka’s highest peak Mullayanagiri, misty Baba Budan Giri ranges, dramatic waterfalls, and verdant coffee estates where coffee was first cultivated in India.', 'Chikkamagaluru', 'September to March', '2 - 4 Days', 'Crisp mountain climate, scenic mist, pleasant year-round (15°C - 28°C)', 13.3161, 75.772, '{"Peak Trekking","Estate Stays","Cloud Bed Viewpoints","Cascading Falls"}', 5, '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/4/4b/Landscape_of_Chikmagalur%2C_karnataka.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Landscape_of_Chikmagalur,_karnataka.jpg","photographer":"Wikimedia Commons / L. Shyamal","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"chikkamagaluru"}', '{"chik-mullayanagiri","chik-baba-budangiri","chik-hebbe-falls","chik-kudremukha","chik-z-point"}')
