VALUES ('vijayanagara', 'Vijayanagara (Hampi)', 'vijayanagara', 'ವಿಜಯನಗರ (ಹಂಪಿ)', 'North Karnataka', 'North Karnataka', 'UNESCO World Heritage Bouldered Marvel', 'The fabled capital of the medieval Vijayanagara Empire with ruins of monolithic stone temples, grand royal enclosures, boulder-strewn hills, and the tranquil Tungabhadra river.', 'Hosapete', 'October to February', '2 - 4 Days', 'Warm sunny days with cool starlit desert-breeze nights (18°C - 32°C)', 15.335, 76.46, '{"Heritage Walks","Boulder Sunsets","Coracle Boat Rides","Temple Architecture"}', 5, '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/dd/Wide_angle_of_Galigopuram_of_Virupaksha_Temple%2C_Hampi_%2804%29_%28cropped%29.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Wide_angle_of_Galigopuram_of_Virupaksha_Temple,_Hampi_(04)_(cropped).jpg","photographer":"Wikimedia Commons / iMahesh","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"vijayanagara"}', '{"hampi-virupaksha","hampi-stone-chariot","hampi-lotus-mahal","hampi-matanga-hill","hampi-coracle-ride"}')
