VALUES ('shivamogga', 'Shivamogga (Shimoga)', 'shivamogga', 'ಶಿವಮೊಗ್ಗ', 'Malnad', 'Malnad', 'Gateway to the Western Ghats & Thunderous Waterfalls', 'The verdant cradle of nature featuring India’s second-highest plunge waterfall (Jog Falls), Agumbe rainforest (Cherrapunji of the South), and mysterious Kodachadri peaks.', 'Shivamogga', 'July to February', '2 - 4 Days', 'High monsoon rainfall, misty hilltops, refreshing forest air', 13.9299, 75.5681, '{"Waterfall Splendor","Rainforest Treks","King Cobra Trails","Sunset Viewpoints"}', 4, '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/f/f5/Jog_Falls_05092016.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Jog_Falls_05092016.jpg","photographer":"Wikimedia Commons / Nikhilb239","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"shivamogga"}', '{"shiv-jog-falls","shiv-agumbe-sunset","shiv-kodachadri","shiv-sakrebyle"}')
