VALUES ('bagalkote', 'Bagalkote (Badami & Pattadakal)', 'bagalkote', 'ಬಾಗಲಕೋಟೆ', 'North Karnataka', 'North Karnataka', 'Cradle of Chalukyan Rock-Cut Architecture', 'The ancient capital of the early Chalukyas, featuring dramatic red sandstone cave temples carved into cliffs overlooking Agastya Lake, and the UNESCO World Heritage monuments of Pattadakal.', 'Bagalkote', 'October to February', '2 - 3 Days', 'Dry and sunny with scenic golden-hour cliff illumination', 15.9187, 75.6766, '{"Cave Exploration","Agastya Lake Reflections","UNESCO Temples","Jolada Rotti Feasts"}', 4, '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/1/10/Badami-cave-temples.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Badami-cave-temples.JPG","photographer":"Wikimedia Commons / rajeshodayanchal","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"bagalkote"}', '{"bgk-badami-caves","bgk-pattadakal","bgk-aihole","bgk-banashankari"}')
