-- 2. DESTINATIONS (49 records)
INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('coorg-abbey-falls', 'Abbey Falls', 'abbey-falls', 'kodagu', 'Kodagu (Coorg)', '{"Nature","Waterfalls","Photography"}', 'A spectacular 70-foot roaring waterfall cascading amidst private coffee plantations and spice estates.', 'Abbey Falls (also called Abbi Falls) is located near Madikeri in the Western Ghats. The Kaveri river tributary plunges down slick black rocks into a calm pool below, framed by tall trees laden with pepper vines and wild coffee shrubs. A hanging bridge across the gushing stream offers panoramic photo angles.', '{"Stunning curtain cascade surrounded by coffee and cardamom bushes","Scenic hanging suspension bridge with misty spray on your face","Short 10-minute rainforest walk down stone steps from the parking lot"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/7/7a/Abbey_Falls_New.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Abbey_Falls_New.jpg","photographer":"Wikimedia Commons / Santhoshkumar Sugumar","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"coorg-abbey-falls"}', '[]', 12.4542, 75.7196, '1.5 Hours', true, 15, '₹15 per person', '9:00 AM – 5:00 PM Daily', '{"July","August","September","October","November","December"}', 4.8, '{"Waterfall Viewing","Nature Photography","Spice Estate Walk"}', false, true, 'Moderate stairway descent (approx 150 steps); paved path with railings.')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('coorg-rajas-seat', 'Raja''s Seat', 'rajas-seat', 'kodagu', 'Kodagu (Coorg)', '{"Viewpoints","Relaxation","Photography","Heritage"}', 'Historic brick and mortar pavilion atop a cliff offering spellbinding sunset views over rolling valleys.', 'Raja''s Seat (Seat of the King) was the favored evening retreat for the Kodagu Kings of Haleri dynasty. Perched on a high ridge in Madikeri, the pavilion overlooks endless layers of mist-shrouded green hills, seasonal flowerbeds, musical fountains, and mesmerizing sunset vistas.', '{"Breathtaking panoramic sunset over Western Ghats valleys","Manicured seasonal flower gardens and tranquil seating","Toy train ride and musical dancing fountain in the evening"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/1/13/Raja%27s_Seat_%28Madikeri%29_%2816%29.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Raja%27s_Seat_(Madikeri)_(16).jpg","photographer":"Wikimedia Commons / Vinayaraj","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"coorg-rajas-seat"}', '[]', 12.4172, 75.7368, '1.5 Hours', true, 10, '₹10 entry, ₹20 musical fountain', '6:00 AM – 8:00 PM Daily', '{"October","November","December","January","February","March"}', 4.8, '{"Sunset Watching","Valley Photography","Garden Walk","Toy Train Ride"}', false, true, 'Wheelchair friendly paved walkways across the central garden area.')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('coorg-dubare-elephant-camp', 'Dubare Elephant Camp', 'dubare-elephant-camp', 'kodagu', 'Kodagu (Coorg)', '{"Wildlife","Nature","Adventure"}', 'Eco-tourism reserve on the banks of River Kaveri where visitors can witness elephant bathing and feeding.', 'Dubare is an elephant training camp set on an island surrounded by the clear Kaveri river waters. Maintained by Karnataka Forest Department and Jungle Lodges, visitors take a riverboat or coracle crossing to watch naturalists scrub, bathe, and feed majestic elephants.', '{"Interactive morning elephant bathing session right in the river","Scenic Kaveri river boat crossing surrounded by deciduous forest","River rafting and tranquil riverside birdwatching"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/9/97/Kaveri_by_Dubare_Forest.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kaveri_by_Dubare_Forest.jpg","photographer":"Wikimedia Commons / Ashwin Geet Dsa","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"coorg-dubare-elephant-camp"}', '[]', 12.3683, 75.9056, '2.5 Hours', true, 100, '₹100 entry + boat crossing', '9:00 AM – 11:30 AM & 4:30 PM – 5:30 PM', '{"September","October","November","December","January","February","March"}', 4.8, '{"Elephant Interaction","Coracle Ride","Birdwatching","River Rafting"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('coorg-talakaveri', 'Talakaveri & Brahmagiri', 'talakaveri', 'kodagu', 'Kodagu (Coorg)', '{"Spiritual","Trekking","Viewpoints"}', 'The sacred birthplace of holy River Kaveri at the foothills of Brahmagiri mountain ridge.', 'Located at 1,276 meters altitude on Brahmagiri hills, Talakaveri is considered holy ground where the sacred Kaveri spring bubbles forth from a small water tank. A climb of 350 stone steps to the summit of Brahmagiri provides 360-degree views of mist-clad undulating hills.', '{"Revered origin temple with tranquil holy water kund","Panoramic summit climb with breezy ridge vistas","Dramatic clouds rolling across mountain borders into Kerala"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Thalakkaveri_Temple%2C_Karnataka.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Thalakkaveri_Temple,_Karnataka.jpg","photographer":"Wikimedia Commons / Pranchiyettan","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"coorg-talakaveri"}', '[]', 12.3853, 75.4925, '2 Hours', false, 0, 'Free entry', '6:00 AM – 6:30 PM Daily', '{"September","October","November","December","January","February"}', 4.8, '{"Temple Darshan","Brahmagiri Hill Steps Climb","Cloud Gazing"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('coorg-madikeri-fort', 'Madikeri Fort & Palace', 'madikeri-fort', 'kodagu', 'Kodagu (Coorg)', '{"History","Heritage","Culture"}', '17th-century historic citadel featuring twin life-sized masonry elephants and a heritage museum.', 'Built originally of mud by Mudduraja and rebuilt in stone by Tipu Sultan, this polygonal hilltop fortress houses a two-storey royal palace, an old Anglican Gothic church converted into an archaeological museum, and stone elephants guarding the ramparts.', '{"Historic ramparts offering vantage views over Madikeri town","Rare museum artifacts from Kodava warrior heritage and British era","Unique synthesis of European and local Mysore architectural styles"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/c/c8/Madikeri_Palace_now_used_as_district_administration_seat.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Madikeri_Palace_now_used_as_district_administration_seat.jpg","photographer":"Wikimedia Commons / VASANTH S.N.","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"coorg-madikeri-fort"}', '[]', 12.4208, 75.7397, '1.5 Hours', false, 0, 'Free entry; museum ₹10', '10:00 AM – 5:30 PM (Closed Mondays)', '{"October","November","December","January","February"}', 4.8, '{"Heritage Walk","Museum Exploration","Rampart Stroll"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('chik-mullayanagiri', 'Mullayanagiri Peak', 'mullayanagiri', 'chikkamagaluru', 'Chikkamagaluru', '{"Trekking","Nature","Viewpoints","Adventure"}', 'The highest peak in Karnataka (1,930 m) famous for chilly winds, rolling green ridges, and sea-of-clouds sunrises.', 'Mullayanagiri is the crowning jewel of the Chandra Drona hill range. At 1,930 meters above sea level, it stands as Karnataka’s highest summit. The peak is named after the revered sage Mullappa Swamy who meditated in a small cave near the summit temple. Visitors ascend approximately 450 steps from the vehicle parking point through blanket mist.', '{"Highest geographical elevation in the state of Karnataka","Spectacular carpet of clouds drifting over mountain saddles","Exciting narrow ridge drive and refreshing mountain breeze"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Mullayanagiri_Peak.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mullayanagiri_Peak.jpg","photographer":"Wikimedia Commons / Ravichandra","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"chik-mullayanagiri"}', '[]', 13.3916, 75.7214, '2.5 Hours', false, 0, 'Free entry', '6:00 AM – 6:00 PM (Best at early sunrise)', '{"September","October","November","December","January","February"}', 4.8, '{"Summit Trekking","Cloud Bed Photography","Temple Visit","Sunrise Watching"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('chik-baba-budangiri', 'Baba Budangiri (Datta Peeta)', 'baba-budangiri', 'chikkamagaluru', 'Chikkamagaluru', '{"Spiritual","History","Nature","Viewpoints"}', 'Sacred mountain range venerated by Sufi saint Baba Budan and Dattatreya, birthplace of Indian coffee.', 'Baba Budangiri holds deep historical significance as the place where Sufi saint Hazrat Baba Budan planted seven smuggled coffee beans from Mocha, Yemen in 1670, birthing India’s coffee heritage. The shrine sits within a rock cavern surrounded by dramatic ravines and winding mountain curves.', '{"Historic birthplace of the Indian coffee revolution","Sacred multi-faith rock cavern shrine surrounded by towering ridges","Magnificent drive overlooking deep gorges and silver oak coffee estates"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/a0/Baba_budan_giri.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Baba_budan_giri.jpg","photographer":"Wikimedia Commons / Nandishsg","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"chik-baba-budangiri"}', '[]', 13.4215, 75.7687, '2 Hours', false, 0, 'Free entry', '8:00 AM – 6:00 PM', '{"September","October","November","December","January","February"}', 4.8, '{"Shrine Darshan","Scenic Drive","Photography","Curative Spring Visit"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('chik-hebbe-falls', 'Hebbe Falls', 'hebbe-falls', 'chikkamagaluru', 'Chikkamagaluru', '{"Nature","Waterfalls","Adventure"}', 'Exotic two-stage waterfall plunging 550 feet inside a dense coffee estate near Kemmanagundi.', 'Hebbe Falls cascades down in two magnificent stages—Dodda Hebbe (Big Falls) and Chikka Hebbe (Small Falls). The stream is infused with medicinal herbs as it flows through pristine forest reserves. Reaching the falls requires an exhilarating 4x4 forest jeep safari followed by a 1-km nature trek crossing gurgling streams.', '{"Thrilling 4x4 open-jeep off-road trail through coffee forests","Two-tiered roaring cascade with crystal clear natural bathing pool","Surrounded by wild orchids, ferns, and untouched shola ecology"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/7/7a/Hebbe_Falls.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hebbe_Falls.JPG","photographer":"Wikimedia Commons / Man On Mission","license":"Public domain","attribution":"Wikimedia Commons / Public domain","placeId":"chik-hebbe-falls"}', '[]', 13.5417, 75.7314, '3 Hours', true, 400, 'Jeep ride approx ₹400 per person', '8:00 AM – 4:00 PM', '{"August","September","October","November","December","January"}', 4.8, '{"Jeep Safari","Forest Trekking","Natural Pool Dipping"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('chik-kudremukha', 'Kudremukha National Park & Peak', 'kudremukha-peak', 'chikkamagaluru', 'Chikkamagaluru', '{"Trekking","Wildlife","Nature","Adventure"}', 'Horse-face shaped summit and protected shola grassland national park rich in biodiversity.', 'Named after its distinctive side profile resembling a horse’s face (Kudre = Horse, Mukha = Face), Kudremukha is a biodiversity hotspot. Rolling emerald shola grasslands, deep jungle valleys, and crystal clear streams make it one of South India’s most prized trekking paradises.', '{"Endless undulating green shola grassland landscapes","Pristine trekking trail with forest department permits","Habitat for lion-tailed macaques, hornbills, and spotted deer"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/8/8d/Kudremukh_National_Park.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kudremukh_National_Park.jpg","photographer":"Wikimedia Commons / Satya swami kiran bandi","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"chik-kudremukha"}', '[]', 13.2144, 75.2575, '5 - 6 Hours', true, 600, 'Forest permit approx ₹600 per trekker', '6:00 AM – 5:00 PM (Requires prior online trek permit)', '{"October","November","December","January","February"}', 4.8, '{"Day Trekking","Wildlife Spotting","Landscape Photography"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('chik-z-point', 'Z Point Kemmangundi', 'z-point-kemmangundi', 'chikkamagaluru', 'Chikkamagaluru', '{"Trekking","Viewpoints","Nature"}', 'Thrilling ridge-edge viewpoint overlooking deep valleys and Western Ghats mountain curves.', 'Z Point is a thrilling 3-km cliff trek starting from the Kemmanagundi horticultural gardens. The trail traces a narrow cliff edge with deep abyss on one side and green mountain slopes on the other, culminating in a jaw-dropping viewpoint of deep wooded valleys and Shanti Falls.', '{"Exhilarating cliff walk along a gentle mountain ridge","Panoramic 360-degree vista of the Western Ghats ranges","Shanti Falls stream along the trek trail"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/6/64/Kemmangundi_fog.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kemmangundi_fog.JPG","photographer":"Wikimedia Commons / Amarrg at English Wikipedia","license":"Public domain","attribution":"Wikimedia Commons / Public domain","placeId":"chik-z-point"}', '[]', 13.5512, 75.7592, '2.5 Hours', false, 0, 'Free entry', '6:00 AM – 6:00 PM', '{"September","October","November","December","January","February"}', 4.8, '{"Cliff Trail Walking","Sunrise / Sunset Watching","Stream Refreshment"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('mysore-palace', 'Mysore Palace (Amba Vilas)', 'mysore-palace', 'mysuru', 'Mysuru (Mysore)', '{"History","Heritage","Culture","Photography"}', 'The magnificent Indo-Saracenic royal seat of the Wodeyars, illuminated by 100,000 golden bulbs on weekends.', 'Commissioned by the royal family and designed by British architect Henry Irwin, Mysore Palace is one of India’s most visited architectural marvels. The palace features grand durbar halls, intricately carved teakwood ceilings, peacock stained-glass domes, solid silver doors, and an opulent collection of royal weaponry.', '{"World-famous royal palace with dazzling glass domes and golden thrones","Mesmerizing Sunday evening illumination with 97,000+ golden bulbs","Rich historical galleries showcasing royal carriages, weaponry, and paintings"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Mysore_Palace_Morning.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mysore_Palace_Morning.jpg","photographer":"Wikimedia Commons / Muhammad Mahdi Karim","license":"GFDL 1.2","attribution":"Wikimedia Commons / GFDL 1.2","placeId":"mysore-palace"}', '[]', 12.3051, 76.6551, '2.5 Hours', true, 100, '₹100 Indians, ₹200 Foreigners', '10:00 AM – 5:30 PM (Illumination Sun & holidays 7:00 PM – 7:45 PM)', '{"September","October","November","December","January","February","March"}', 4.8, '{"Palace Guided Tour","Night Illumination Viewing","Royal Museum Walk"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('mysore-chamundi-hill', 'Chamundi Hill & Sri Chamundeshwari Temple', 'chamundi-hill', 'mysuru', 'Mysuru (Mysore)', '{"Spiritual","Viewpoints","Heritage"}', 'Historic hilltop temple dedicated to the patron goddess of Mysuru, overlooking the entire heritage city.', 'Rising 1,000 meters above sea level, Chamundi Hill is crowned by the 17th-century Dravidian temple of Goddess Chamundeshwari. En route lies the legendary 5-meter monolithic Nandi bull carved from a single granite boulder in 1659.', '{"Revered Shakti shrine with towering 7-tiered gopuram","Giant monolithic black granite Nandi Bull statue halfway up","Stunning bird’s-eye panorama of Mysore Palace, Race Course, and lakes"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d1/Chamundeshwari_Temple_Mysore.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Chamundeshwari_Temple_Mysore.jpg","photographer":"Wikimedia Commons / Rithwik","license":"Public domain","attribution":"Wikimedia Commons / Public domain","placeId":"mysore-chamundi-hill"}', '[]', 12.2724, 76.6713, '2 Hours', false, 0, 'Free (Special darshan ₹100)', '7:30 AM – 2:00 PM & 3:30 PM – 6:00 PM & 7:30 PM – 9:00 PM', '{"September","October","November","December","January","February"}', 4.8, '{"Temple Darshan","City Skyline Viewing","1000-Step Pilgrimage Stairway Walk"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('mysore-brindavan-gardens', 'Brindavan Gardens (KRS Dam)', 'brindavan-gardens', 'mysuru', 'Mysuru (Mysore)', '{"Relaxation","Photography","Nature"}', 'Terraced ornamental gardens adjoining the Krishnarajasagara Dam across the Kaveri River with musical fountains.', 'Laid out over 60 acres in the 1930s under Sir Mirza Ismail, Brindavan Gardens features manicured lawns, topiaries, cascades, and vibrant flower beds directly below the Krishna Raja Sagara reservoir dam. Its evening musical fountain show set to classical and film music draws thousands.', '{"Grand terraced Mughal-style garden architecture","Evening illuminated dancing fountains synchronized to music","Boating on the expansive Kaveri river reservoir"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Brindavan_Gardens.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Brindavan_Gardens.JPG","photographer":"Wikimedia Commons / Joe Ravi","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"mysore-brindavan-gardens"}', '[]', 12.4257, 76.5728, '2 Hours', true, 50, '₹50 adults, ₹10 children', '6:30 AM – 9:00 PM (Fountain show 6:30 PM – 7:30 PM)', '{"October","November","December","January","February","March"}', 4.8, '{"Garden Stroll","Musical Fountain Show","Boating"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('mysore-somnathpur-temple', 'Somnathpur Chennakesava Temple', 'somnathpur-temple', 'mysuru', 'Mysuru (Mysore)', '{"Heritage","History","Culture"}', 'UNESCO World Heritage 13th-century trikuta Hoysala masterpiece with intricate soapstone friezes.', 'Built in 1268 CE by Hoysala commander Somnatha, this star-shaped temple is an architectural marvel. Every square inch of the soapstone walls is adorned with exquisite friezes depicting caparisoned elephants, charging horses, mythological battles, musicians, and celestial nymphs.', '{"UNESCO World Heritage Sacred Ensembles of the Hoysalas","Astonishingly preserved soapstone ceiling rosettes and wall relief sculptures","Peaceful rural surroundings away from city crowds"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/f/fc/Prakara_with_lathe_turned_pillars_at_Chennakesava_temple_at_Somanathapura.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Prakara_with_lathe_turned_pillars_at_Chennakesava_temple_at_Somanathapura.jpg","photographer":"Wikimedia Commons / Tsohil","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"mysore-somnathpur-temple"}', '[]', 12.2764, 76.8817, '1.5 Hours', true, 25, '₹25 Indians, ₹300 Foreigners', '9:00 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Architectural Photography","Archaeological Tour","History Study"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('mysore-st-philomenas', 'St. Philomena''s Cathedral', 'st-philomenas-cathedral', 'mysuru', 'Mysuru (Mysore)', '{"Heritage","Culture","Spiritual"}', 'One of India’s tallest neo-Gothic cathedrals, styled after Germany’s Cologne Cathedral.', 'Constructed in 1936 under Maharaja Nalvadi Krishnaraja Wadiyar, this cathedral features two twin spires towering 175 feet into the sky. Inside, stained glass windows crafted in France depict scenes from Christ’s life, leading to an underground crypt containing relics of St. Philomena.', '{"Soaring twin neo-Gothic spires and French stained glass artistry","Subterranean sacred crypt with marble altar","Testament to the secular royal patronage of the Wodeyars"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/c/c5/St._Philomena_Cathedral_Mysore.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:St._Philomena_Cathedral_Mysore.jpg","photographer":"Wikimedia Commons / DEB ANUTOSH","license":"CC BY-SA 2.0","attribution":"Wikimedia Commons / CC BY-SA 2.0","placeId":"mysore-st-philomenas"}', '[]', 12.3204, 76.6582, '1 Hour', false, 0, 'Free entry', '5:00 AM – 6:00 PM Daily', '{"All Year Round"}', 4.8, '{"Architecture Appreciation","Silent Prayer","Stained Glass Viewing"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hampi-virupaksha', 'Virupaksha Temple', 'virupaksha-temple', 'vijayanagara', 'Vijayanagara (Hampi)', '{"Heritage","History","Spiritual","Culture"}', 'Continuous living 7th-century Shiva shrine with a 50-meter gopuram along Hampi Bazaar.', 'The oldest active temple in Hampi, dedicated to Lord Shiva as Virupaksha, consort of local goddess Pampa. Its towering eastern gateway presides over the ancient Hampi Bazaar street. The inner sanctum features an optical pinhole camera effect casting an inverted shadow of the gopuram on the temple wall.', '{"Unbroken living temple worship spanning over 1,300 years","Intricate pillared mandapas and temple elephant Lakshmi blessings","Famous natural pinhole camera inverted shadow phenomenon"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Complex_of_Virupaksha_Temple%2C_Hampi_%2804%29.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Complex_of_Virupaksha_Temple,_Hampi_(04).jpg","photographer":"Wikimedia Commons / iMahesh","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hampi-virupaksha"}', '[]', 15.335, 76.46, '2 Hours', true, 50, '₹50 entry, camera ₹50', '6:00 AM – 1:00 PM & 5:00 PM – 9:00 PM', '{"October","November","December","January","February"}', 4.8, '{"Temple Darshan","Ancient Architecture Walk","Elephant Blessing"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hampi-stone-chariot', 'Stone Chariot & Vijaya Vittala Temple', 'stone-chariot-vittala', 'vijayanagara', 'Vijayanagara (Hampi)', '{"Heritage","History","Culture","Photography"}', 'Iconic monolithic stone chariot depicted on the ₹50 currency note, and 56 musical acoustic pillars.', 'The pinnacle of Vijayanagara artistic achievement, the 15th-century Vittala complex houses the world-renowned Garuda Stone Chariot. Its intricate carvings simulate wooden construction with revolving wheels. The Maha Mandapa contains 56 musical pillars that emit musical notes when lightly tapped.', '{"One of India’s most iconic heritage monuments (featured on Indian currency)","Acoustic musical pillars of the Ranga Mandapa","Expansive paved courtyard with King’s Balance and gateway ruins"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/c/cb/Stone_Chariot%2C_Hampi_2.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Stone_Chariot,_Hampi_2.jpg","photographer":"Wikimedia Commons / Ajayreddykalavalli","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hampi-stone-chariot"}', '[]', 15.3377, 76.4789, '2.5 Hours', true, 40, '₹40 (ASI combo ticket covers Zenana Enclosure)', '8:30 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Chariot Photography","Acoustic Architecture Tour","Courtyard Walk"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hampi-lotus-mahal', 'Lotus Mahal & Elephant Stables', 'lotus-mahal-zenana', 'vijayanagara', 'Vijayanagara (Hampi)', '{"Heritage","History","Culture"}', 'Indo-Islamic royal pleasure pavilion with lotus-bud arches and domed chambers for eleven royal tuskers.', 'Set within the walled Zenana Enclosure, Lotus Mahal is a graceful two-storey secular structure displaying an elegant blend of Islamic cusped arches and Hindu plinth carvings. Nearby stand the grandiose Elephant Stables, featuring eleven interconnected domed chambers built to stable royal elephants.', '{"Exquisite Indo-Islamic secular architecture with open balconies","Massive 11-domed royal elephant stables with grand symmetry","Lush manicured royal garden lawn with watchtowers"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/ac/Flat_elevation_of_Lotus_Mahal%2C_Hampi_%28Closeup%29.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Flat_elevation_of_Lotus_Mahal,_Hampi_(Closeup).jpg","photographer":"Wikimedia Commons / iMahesh","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hampi-lotus-mahal"}', '[]', 15.3204, 76.471, '2 Hours', true, 40, 'Included in ASI combo ticket (₹40)', '8:30 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Royal Ruins Tour","Architecture Photography","Lawn Relaxation"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hampi-matanga-hill', 'Matanga Hill Sunrise', 'matanga-hill', 'vijayanagara', 'Vijayanagara (Hampi)', '{"Viewpoints","Trekking","Photography","Adventure"}', 'Highest vantage point in central Hampi offering an unforgettable 360-degree panorama of boulder fields.', 'Mentioned in the Ramayana as the hermitage of Sage Matanga, this rocky peak in the heart of Hampi rewards an adventurous early morning scramble with the finest sunrise view in South India. Watch golden dawn rays illuminate ancient temple gopurams, banana plantations, and the winding Tungabhadra River.', '{"Unrivaled 360-degree sunrise view over the entire Hampi ruins complex","Surreal bouldered moonscape illuminated by golden morning light","Rooftop rooftop Veerabhadra temple on the summit"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Enroute_to_Matanga_hills%2C_Hampi.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Enroute_to_Matanga_hills,_Hampi.jpg","photographer":"Wikimedia Commons","license":"CC BY-SA","attribution":"Wikimedia Commons / CC BY-SA","placeId":"hampi-matanga-hill"}', '[]', 15.333, 76.4682, '2 Hours', false, 0, 'Free entry', '5:30 AM – 6:30 PM (Best at dawn)', '{"October","November","December","January","February"}', 4.8, '{"Dawn Hill Scramble","Landscape Photography","Sunrise Meditation"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hampi-coracle-ride', 'Tungabhadra Coracle Ride & Anegundi', 'tungabhadra-coracle-ride', 'vijayanagara', 'Vijayanagara (Hampi)', '{"Adventure","Nature","Culture"}', 'Glide across the boulder-framed Tungabhadra River in traditional round woven bamboo coracles.', 'Coracles (dongi) have navigated the swift Tungabhadra waters since the Vijayanagara era. A boatman spins the circular craft between giant granite boulders and prehistoric water carvings, reaching mythological Kishkindha and the tranquil ruins of Anegundi.', '{"Authentic ancient watercraft navigation between giant river boulders","Water-level views of river carvings and submerged temple steps","Cross over to relaxed hippie villages and paddy fields of Anegundi"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Hampi%2C_Tungabhadra_River%2C_India.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hampi,_Tungabhadra_River,_India.jpg","photographer":"Wikimedia Commons / Vyacheslav Argenberg","license":"CC BY 4.0","attribution":"Wikimedia Commons / CC BY 4.0","placeId":"hampi-coracle-ride"}', '[]', 15.3385, 76.4632, '1.5 Hours', true, 150, '₹150 – ₹300 per person for boat ride', '8:00 AM – 5:30 PM', '{"October","November","December","January","February"}', 4.8, '{"Coracle Boating","River Photography","Village Exploration"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('uk-om-beach', 'Om Beach Gokarna', 'om-beach-gokarna', 'uttara-kannada', 'Uttara Kannada (Gokarna & Dandeli)', '{"Beaches","Nature","Relaxation","Adventure"}', 'Famous naturally formed beach resembling the sacred Hindu Om symbol with rocky coves and cliff cafes.', 'Om Beach is named after its twin curved crescents that naturally form the spiritual "Om" (ॐ) symbol. Lined with rocky outcroppings, sea-facing shacks serving fresh fish and coconut water, and gentle turquoise waves, it is a haven for beach lovers, cliff trekkers, and water sports enthusiasts.', '{"Unique natural coastline shaped like the auspicious Om symbol","Dramatic rocky headlands with gentle ocean waves for swimming","Gateway to the famous Gokarna five-beach cliff trek"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Om_Beach_Gokarna_%28259788351%29.jpeg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Om_Beach_Gokarna_(259788351).jpeg","photographer":"Wikimedia Commons / Shreeram Kushwaha","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"uk-om-beach"}', '[]', 14.5186, 74.3168, '3 Hours', false, 0, 'Free entry', 'Open 24 hours (Best daytime & sunset)', '{"October","November","December","January","February","March"}', 4.8, '{"Beach Trekking","Speedboat Ride","Sunset Watching","Cafe Hopping"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('uk-murudeshwar', 'Murudeshwara Temple & Giant Shiva Statue', 'murudeshwara-temple', 'uttara-kannada', 'Uttara Kannada (Gokarna & Dandeli)', '{"Spiritual","Heritage","Viewpoints"}', 'World’s second-tallest Shiva statue (123 ft) surrounded on three sides by the azure Arabian Sea.', 'Perched atop Kanduka Hill peninsula jutting into the Arabian Sea, Murudeshwara is famous for its 123-foot colossal silver-hued Shiva statue and the 20-storey Raja Gopuram. An elevator inside the gopuram transports visitors to the 18th floor for breathtaking sea and statue views.', '{"Colossal 123-foot Shiva statue overlooking azure ocean waters","Elevator ride to the top of 249-foot Raja Gopuram for ocean views","Spiritual energy combined with pristine coastal beach scenery"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/4/41/Lord_shiva_Murudeshwara_Temple.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Lord_shiva_Murudeshwara_Temple.JPG","photographer":"Wikimedia Commons / Iramuthusamy","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"uk-murudeshwar"}', '[]', 14.0941, 74.4849, '2.5 Hours', false, 0, 'Free entry; gopuram lift ₹20', '6:00 AM – 1:00 PM & 3:00 PM – 8:30 PM', '{"October","November","December","January","February","March"}', 4.8, '{"Temple Darshan","Gopuram Lift Tour","Statue Photography","Beach Walk"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('uk-yana-rocks', 'Yana Limestone Monoliths', 'yana-rocks', 'uttara-kannada', 'Uttara Kannada (Gokarna & Dandeli)', '{"Nature","Trekking","Spiritual","Adventure"}', 'Two mysterious jagged crystalline black limestone karst towers rising out of Sahyadri evergreen forests.', 'Hidden deep inside the Sahyadri rainforest near Sirsi, Yana features two towering monolithic rock formations: Bhairaveshwara Shikhara (120 meters) and Mohini Shikhara (90 meters). A natural cave underneath the towering monolith enshrines a self-manifested Shiva Lingam trickled by mountain spring water.', '{"Dramatic dark karst rock towers rising above thick jungle canopy","Natural cavern pass with dripping mineral stalactites and bats","Peaceful 1.5-km forested nature trek through biodiversity corridor"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/f/fc/Yana_Rocks.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Yana_Rocks.jpg","photographer":"Wikimedia Commons / Amithkk","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"uk-yana-rocks"}', '[]', 14.5888, 74.5614, '2.5 Hours', true, 20, '₹20 entry + vehicle parking', '8:00 AM – 6:00 PM', '{"October","November","December","January","February"}', 4.8, '{"Forest Trail Hike","Cave Exploration","Geological Photography"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('uk-dandeli-rafting', 'Dandeli Kali River Adventure', 'dandeli-kali-river', 'uttara-kannada', 'Uttara Kannada (Gokarna & Dandeli)', '{"Adventure","Wildlife","Nature"}', 'Grade 3 white-water rafting, natural jacuzzis, and hornbill birdwatching along River Kali.', 'Dandeli is Karnataka’s adventure hub nestled in the dense deciduous jungles of the Western Ghats. The rushing waters of River Kali offer thrilling Class II to Class III rapids, natural rock jacuzzi baths, kayaking, and jungle safaris home to the elusive black panther.', '{"Exciting white water rafting rapids guided by certified river masters","Natural river jacuzzi rapids massaging tired muscles","Home to four species of hornbills and dense deciduous jungle"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/5/53/Dandeli_1.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Dandeli_1.jpg","photographer":"Wikimedia Commons / Vinayak wiki","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"uk-dandeli-rafting"}', '[]', 15.2415, 74.6225, '3.5 Hours', true, 1, 'Rafting packages approx ₹1,200 – ₹1,800', '8:30 AM – 5:00 PM', '{"October","November","December","January","February","March","April"}', 4.8, '{"White Water Rafting","Natural Jacuzzi Bath","Kayaking","Jungle Safari"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('uk-kudle-beach', 'Kudle Beach Gokarna', 'kudle-beach-gokarna', 'uttara-kannada', 'Uttara Kannada (Gokarna & Dandeli)', '{"Beaches","Relaxation","Food","Photography"}', 'A serene horseshoe-shaped sandy bay flanked by hillocks, famous for golden sunsets and laid-back cafes.', 'Tucked between two green headlands just south of Gokarna town, Kudle is a wide, crescent-shaped sandy beach. With gentle surf perfect for swimming and a string of chilled-out seafood cafes, it is the ideal spot to unwind, read, do yoga, or watch evening fire performers.', '{"Wide golden sand crescent with safe gentle swimming waters","Chilled-out beach cafes serving wood-fired pizzas and fresh coconut juice","Spectacular uninterrupted sunset views into the Arabian Sea horizon"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/a/a6/Kudle_Beach%2C_Gokarna.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kudle_Beach,_Gokarna.jpg","photographer":"Wikimedia Commons / Malavikanandan30","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"uk-kudle-beach"}', '[]', 14.5298, 74.3142, '2.5 Hours', false, 0, 'Free entry', 'Open 24 hours', '{"October","November","December","January","February","March"}', 4.8, '{"Beach Walk","Swimming","Sunset Watching","Yoga on the Sand"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('udupi-st-marys', 'St. Mary''s Island', 'st-marys-island', 'udupi', 'Udupi', '{"Nature","Beaches","Photography","Adventure"}', 'National Geological Monument of unique columnar hexagonal basalt lava rock formations jutting from turquoise sea.', 'Formed by sub-aerial subvolcanic activity 88 million years ago when Madagascar split from India, St. Mary’s Islands boast vertical hexagonal basalt pillars found only in few places on Earth (such as Giant’s Causeway in Ireland). Reached by a scenic 20-minute ferry from Malpe beach.', '{"Rare UNESCO-listed hexagonal columnar basalt rock geometry","Crystal clear turquoise waters and seashell-studded white sands","Scenic ocean ferry crossing from Malpe Harbor"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b8/St._Mary%27s_Island%2C_Udupi.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:St._Mary%27s_Island,_Udupi.jpg","photographer":"Wikimedia Commons / Shravan Kamath94","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"udupi-st-marys"}', '[]', 13.3768, 74.6738, '3 Hours', true, 350, 'Ferry ticket approx ₹350 per person', '9:00 AM – 5:00 PM (Closed during monsoons May-Sept)', '{"October","November","December","January","February","March","April"}', 4.8, '{"Geological Rock Exploration","Ferry Ride","Seashell Collecting","Photography"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('udupi-krishna-matha', 'Sri Krishna Matha & Kanakana Kindi', 'udupi-sri-krishna-temple', 'udupi', 'Udupi', '{"Spiritual","Heritage","Culture","Food"}', 'Ancient 13th-century Vaishnavite temple founded by saint Madhvacharya, viewed through the silver-plated window.', 'The spiritual heart of Tulu Nadu, the temple honors Lord Krishna in balarupa (childhood form). Legend holds that when saint-poet Kanakadasa was barred from entry, the deity turned westward and cracked open the stone wall so the devotee could glimpse him through the famous 9-holed silver window (Kanakana Kindi).', '{"Unique darshan tradition through the sacred Kanakana Kindi window","World-famous divine vegetarian temple meal (Maha Prasada) served on plantain leaves","Sacred Madhwa Sarovara holy tank and golden temple chariot"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Udupi_Sri_Krishna_Matha_Temple.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Udupi_Sri_Krishna_Matha_Temple.jpg","photographer":"Wikimedia Commons / Ashok Prabhakaran from Chennai, India","license":"CC BY-SA 2.0","attribution":"Wikimedia Commons / CC BY-SA 2.0","placeId":"udupi-krishna-matha"}', '[]', 13.3409, 74.7421, '2 Hours', false, 0, 'Free entry', '5:30 AM – 9:30 PM', '{"All Year Round"}', 4.8, '{"Temple Darshan","Maha Prasada Tasting","Car Street Walk","Goshala Visit"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('udupi-malpe-beach', 'Malpe Beach & Sea Walkway', 'malpe-beach', 'udupi', 'Udupi', '{"Beaches","Adventure","Relaxation"}', 'Silver sand shoreline with water sports, beach shacks, and a paved breakwater sea walk extending 500m into the waves.', 'Malpe is a major port and leisure beach in Udupi. With fine white sand and gentle Arabian Sea waters, it offers jet skiing, parasailing, and banana rides. A paved sea walkway built atop the sea breakwater allows visitors to walk 500 meters straight out into the ocean.', '{"Exhilarating sea walkway extending right into the crashing waves","Water sports center with parasailing, jet-ski, and camel rides","Boarding jetty for ferries to St. Mary’s Islands"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/4/49/Malpe_Beach_2.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Malpe_Beach_2.jpg","photographer":"Wikimedia Commons / KshitizBathwal / Skyscape Photography","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"udupi-malpe-beach"}', '[]', 13.3541, 74.7022, '2.5 Hours', false, 0, 'Free entry', 'Open 24 hours (Water sports 9:00 AM – 6:00 PM)', '{"October","November","December","January","February","March"}', 4.8, '{"Sea Walk Stroll","Water Sports","Sunset Watching","Street Food Tasting"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('udupi-kapu-lighthouse', 'Kaup (Kapu) Lighthouse & Beach', 'kaup-lighthouse-beach', 'udupi', 'Udupi', '{"Heritage","Viewpoints","Beaches","Photography"}', '1901 black-and-white spiral lighthouse towering 89 feet on a massive coastal rock overlooking crashing waves.', 'Built by the British in 1901, Kapu lighthouse stands dramatically atop a giant black monolith rock on the Arabian shoreline. Visitors can climb the spiral stairs inside during late afternoon for breathtaking views of the coastline, fishing boats, and glowing sunsets.', '{"Climb the historic 120-year-old spiral lighthouse for panoramic coastal vistas","Craggy rocks where roaring waves crash against stone boulders","Picturesque backdrop frequently featured in South Indian films"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Kaup_beach%2C_Udupi%2C_Karnataka_04.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kaup_beach,_Udupi,_Karnataka_04.jpg","photographer":"Wikimedia Commons / Subhashish Panigrahi","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"udupi-kapu-lighthouse"}', '[]', 13.2236, 74.7397, '2 Hours', false, 0, 'Beach free; lighthouse entry ₹10', 'Lighthouse open 4:00 PM – 6:00 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Lighthouse Climb","Rock Clambering","Sunset Photography"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('shiv-jog-falls', 'Jog Falls (Gerosoppa)', 'jog-falls', 'shivamogga', 'Shivamogga (Shimoga)', '{"Nature","Waterfalls","Photography","Viewpoints"}', 'India’s second-highest plunge waterfall, dropping 830 feet in four distinct cascades: Raja, Roarer, Rocket, and Rani.', 'Created by the Sharavathi River plunging off a rugged cliff in the Western Ghats, Jog Falls drops 253 meters (830 ft) in a single spectacular leap. The four distinct torrents are Raja (regal and unbroken), Roarer (crashing into rocks), Rocket (jetting through narrow crevice), and Rani (graceful frothing sheet).', '{"One of the most thunderous and majestic waterfall spectacles in Asia","Climb down 1,400 steps to the misty base pool of the gorge","Sensational viewpoints from British bungalow and Watkins platform"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/f/f5/Jog_Falls_05092016.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Jog_Falls_05092016.jpg","photographer":"Wikimedia Commons / Nikhilb239","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"shiv-jog-falls"}', '[]', 14.2285, 74.8122, '3 Hours', true, 15, '₹15 entry + vehicle parking', '7:30 AM – 6:30 PM Daily', '{"July","August","September","October","November","December"}', 4.8, '{"Waterfall Viewing","Gorge Steps Descent","Laser Light Show","Photography"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('shiv-agumbe-sunset', 'Agumbe Rainforest & Sunset Viewpoint', 'agumbe-sunset-viewpoint', 'shivamogga', 'Shivamogga (Shimoga)', '{"Nature","Viewpoints","Wildlife","Photography"}', 'The "Cherrapunji of South India" boasting dense primary rainforest, King Cobras, and a sunset over the Arabian Sea horizon.', 'Perched on the edge of the ghats at 825 meters, Agumbe receives over 7,000 mm of annual rainfall. The town is famous for the Agumbe Rainforest Research Station (ARRS) studying King Cobras and the historic Malgudi Days television house. The sunset viewpoint overlooks mist-carpeted coastal valleys reaching all the way to the Arabian Sea.', '{"Mesmerizing sunset overlooking misty valleys descending to the sea","King cobra conservation and pristine tropical rainforest trails","Visit \"Doddamane\", the 150-year-old heritage house featured in RK Narayan’s Malgudi Days"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/4/4d/Agumbe_View_point.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Agumbe_View_point.jpg","photographer":"Wikimedia Commons / Shashidhara halady","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"shiv-agumbe-sunset"}', '[]', 13.5028, 75.0933, '2 Hours', false, 0, 'Free entry', '5:00 AM – 7:00 PM (Best at sunset)', '{"October","November","December","January","February"}', 4.8, '{"Sunset Watching","Rainforest Walk","Malgudi Days Heritage Visit","Herping"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('shiv-kodachadri', 'Kodachadri Mountain Peak', 'kodachadri-peak', 'shivamogga', 'Shivamogga (Shimoga)', '{"Trekking","Adventure","Spiritual","Nature"}', 'Natural heritage peak (1,343 m) where Adi Shankaracharya meditated, surrounded by dense Mookambika forest.', 'Rising in the Mookambika Wildlife Sanctuary, Kodachadri is a sacred mountain where Adi Shankara attained enlightenment at the Sarvajna Peetha stone shrine. Reaching the peak involves an adrenaline-fueled off-road 4x4 jeep track or a demanding 14-km trek through Hidlumane Falls and shola ridges.', '{"Sarvajna Peetha stone shrine dedicated to Adi Shankara","Wild Hidlumane seven-tiered waterfall trek along the trail","Hair-raising 4x4 off-road mountain jeep track"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/c/c1/Kodachadri.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kodachadri.JPG","photographer":"Wikimedia Commons / Magentic Manifestations","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"shiv-kodachadri"}', '[]', 13.8569, 74.8724, '4 - 5 Hours', true, 450, 'Jeep ride approx ₹450 per person', '6:00 AM – 5:00 PM', '{"October","November","December","January","February"}', 4.8, '{"4x4 Jeep Safari","Mountain Trekking","Waterfall Climbing","Sarvajna Peetha Visit"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('shiv-sakrebyle', 'Sakrebyle Elephant Camp', 'sakrebyle-elephant-camp', 'shivamogga', 'Shivamogga (Shimoga)', '{"Wildlife","Nature","Family"}', 'Elephant rehabilitation camp on the backwaters of Gajanur Tunga Dam with morning river-scrubbing interactions.', 'Located 14 km from Shivamogga on the Honnavar road, Sakrebyle is an eco-tourism elephant training camp. Trained mahouts bring the elephants to the Tunga river each morning for a thorough scrubbing and bath, welcoming visitors to participate.', '{"Participate in morning elephant river bathing and mahout grooming","Scenic tranquil backwaters of the Tunga River Gajanur Dam","Family-friendly wildlife eco-tourism experience"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b2/Sakrebailu_Elephant_camp.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sakrebailu_Elephant_camp.jpg","photographer":"Wikimedia Commons / Arun.venkatesh","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"shiv-sakrebyle"}', '[]', 13.8824, 75.5217, '2 Hours', true, 50, '₹50 entry, ₹100 elephant interaction', '8:30 AM – 11:30 AM Daily', '{"October","November","December","January","February","March"}', 4.8, '{"Elephant Interaction","River Edge Walk","Nature Photography"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('dk-panambur-beach', 'Panambur Beach & Harbor', 'panambur-beach', 'dakshina-kannada', 'Dakshina Kannada (Mangaluru)', '{"Beaches","Relaxation","Adventure"}', 'Karnataka’s cleanest recreational beach with lifeguards, international kite festivals, and camel rides.', 'Panambur Beach is one of South India’s most well-maintained beaches, managed by trained lifeguards. Located near New Mangalore Port, visitors can watch cargo vessels glide along the horizon while enjoying jet ski rides, camel safaris, and local beachside fish fry stalls.', '{"Safest beach in the region with trained patrol lifeguards","Exciting water sports, boat cruises, and camel rides along the sand","Host to the famous biennial International Kite Festival"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/2/23/Panambur_Beach_Mangalore.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Panambur_Beach_Mangalore.jpg","photographer":"Wikimedia Commons / CodePanda","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"dk-panambur-beach"}', '[]', 12.9365, 74.8016, '2.5 Hours', false, 0, 'Free entry', 'Open 24 hours (Water sports 8:30 AM – 6:30 PM)', '{"October","November","December","January","February"}', 4.8, '{"Kite Flying","Jet Skiing","Camel Rides","Coastal Snack Tasting"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('dk-kadri-manjunatha', 'Kadri Manjunatha Temple', 'kadri-manjunatha-temple', 'dakshina-kannada', 'Dakshina Kannada (Mangaluru)', '{"Spiritual","Heritage","History"}', '10th-century coastal hilltop shrine housing one of India’s finest bronze Lokeshwara statues.', 'Dating back to the 10th century and reflecting a confluence of Vajrayana Buddhism and Shaivism, this historic temple sits at the base of Kadri hills. It houses a revered 1,000-year-old bronze icon of Lord Lokeshwara with three faces and six arms, alongside natural freshwater hill spring ponds.', '{"Masterpiece 10th-century bronze sculpture of Lord Lokeshwara","Natural perennial mountain spring ponds (Gomukha) for ritual ablutions","Ancient laterite hillside stone caves associated with the Pandavas"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d4/Kadri_temple_entrance_mangalore.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Kadri_temple_entrance_mangalore.jpg","photographer":"Wikimedia Commons / Surfmaster23","license":"CC BY 4.0","attribution":"Wikimedia Commons / CC BY 4.0","placeId":"dk-kadri-manjunatha"}', '[]', 12.8906, 74.8569, '1.5 Hours', false, 0, 'Free entry', '6:00 AM – 1:00 PM & 4:00 PM – 8:30 PM', '{"All Year Round"}', 4.8, '{"Temple Darshan","Bronze Icon Viewing","Spring Pond Tour"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('dk-tannirbhavi-beach', 'Tannirbhavi Beach & Coastal Tree Park', 'tannirbhavi-beach-tree-park', 'dakshina-kannada', 'Dakshina Kannada (Mangaluru)', '{"Beaches","Relaxation","Nature"}', 'Secluded casuarina-fringed beach reached by ferry across the Gurupura River, with an eco tree park.', 'Tannirbhavi is beloved for its tranquility compared to commercial beaches. Visitors cross the Gurupura river on a traditional passenger ferry from Sultan Battery. The beach is flanked by a 15-hectare coastal Tree Park showcasing native coastal flora, boardwalks, and herbal gardens.', '{"Peaceful pine and casuarina forest shade right onto the beach sand","Scenic river passenger ferry crossing from historic Sultan Battery","Boardwalk strolls in the coastal botanical Tree Park"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d8/Tannirubhavi_beach_02.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tannirubhavi_beach_02.JPG","photographer":"Wikimedia Commons / Giridhar1729","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"dk-tannirbhavi-beach"}', '[]', 12.8889, 74.8142, '2 Hours', false, 0, 'Free entry; Tree park ₹10', '6:00 AM – 7:00 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Ferry Crossing","Beach Walks","Tree Park Stroll","Sunset Watching"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('dk-pilikula', 'Pilikula Heritage Village & Biological Park', 'pilikula-nisargadhama', 'dakshina-kannada', 'Dakshina Kannada (Mangaluru)', '{"Culture","Heritage","Wildlife","Family"}', 'Expansive 370-acre eco-cultural center preserving coastal Tulu Nadu traditional crafts and wildlife.', 'Pilikula (meaning "Tiger’s Pond") is an integrated botanical, biological, and heritage center. Its Artisan Village recreates traditional Coastal Karnataka rural life with live pottery, oil pressing, handloom weaving, an open-concept zoo, 3D planetarium, and boating lake.', '{"Authentic working artisan workshops recreating rural Tulu heritage","Modern open-enclosure zoo housing Western Ghats wildlife species","Scenic boating lake and science center with 3D digital planetarium"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/e/e1/Pilikula_Botanical_Garden_-_Footpath.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pilikula_Botanical_Garden_-_Footpath.jpg","photographer":"Wikimedia Commons / Aviator423","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"dk-pilikula"}', '[]', 12.9288, 74.9016, '3 Hours', true, 50, 'Heritage village ₹50, Zoo ₹100', '9:30 AM – 5:30 PM (Closed Mondays)', '{"October","November","December","January","February"}', 4.8, '{"Artisan Village Tour","Zoo Walk","Lake Boating","Planetarium Show"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('blr-bangalore-palace', 'Bangalore Palace', 'bangalore-palace', 'bengaluru-urban', 'Bengaluru Urban', '{"History","Heritage","Culture","Photography"}', 'Tudor-style royal estate modeled on England’s Windsor Castle with fortified towers and battlements.', 'Acquired in 1884 by the Wodeyar Maharajas, this sprawling palace boasts Tudor-style fortified towers, turrets, gothic windows, wood carvings, and lush gardens. The interiors are adorned with 19th-century paintings by Raja Ravi Varma, hunting trophies, and royal family memorabilia.', '{"Striking Tudor architectural facade with crenellated parapets and towers","Grand ballroom and Durbar Hall with stained glass and yellow Spanish tiles","Rare Raja Ravi Varma oil paintings and royal photographic archives"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/0a/Bangalore_Palace_-_Jayamahal.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Bangalore_Palace_-_Jayamahal.jpg","photographer":"Wikimedia Commons / Bikashrd","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"blr-bangalore-palace"}', '[]', 12.9988, 77.5925, '2 Hours', true, 250, '₹250 Indians, ₹450 Foreigners (Includes audio guide)', '10:00 AM – 5:30 PM Daily', '{"All Year Round"}', 4.8, '{"Audio Guided Tour","Architecture Photography","Palace Grounds Walk"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('blr-lalbagh', 'Lalbagh Botanical Garden', 'lalbagh-botanical-garden', 'bengaluru-urban', 'Bengaluru Urban', '{"Nature","Relaxation","History","Photography"}', '240-acre historic garden commissioned by Hyder Ali, housing India’s largest collection of tropical plants and a Crystal Palace Glass House.', 'Commissioned by Hyder Ali in 1760 and completed by Tipu Sultan, Lalbagh houses over 1,800 species of flora, centuries-old baobab trees, and the iconic London Crystal Palace-inspired Glass House. It also features a 3,000-million-year-old Peninsular Gneiss rock formation crowned by a Kempegowda watchtower.', '{"Iconic 19th-century Glass House hosting legendary bi-annual flower shows","Centuries-old rare exotic trees imported from Persia, Kabul, and France","Ancient 3-billion-year-old Peninsular Gneiss Geological Monument"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Glasshouse_and_fountain_at_lalbagh.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glasshouse_and_fountain_at_lalbagh.jpg","photographer":"Wikimedia Commons / Muhammad Mahdi Karim","license":"GFDL 1.2","attribution":"Wikimedia Commons / GFDL 1.2","placeId":"blr-lalbagh"}', '[]', 12.9507, 77.5848, '2.5 Hours', false, 0, '₹30 entry (Free 6:00 AM – 9:00 AM)', '6:00 AM – 7:00 PM Daily', '{"All Year Round (Flower shows in Jan & Aug)"}', 4.8, '{"Botanical Walking Tour","Glass House Viewing","Kempe Gowda Rock Climb","Lakeside Birdwatching"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('blr-cubbon-park', 'Cubbon Park (Sri Chamarajendra Park)', 'cubbon-park', 'bengaluru-urban', 'Bengaluru Urban', '{"Nature","Relaxation","Culture"}', '300-acre green lung in the heart of Bangalore flanked by Vidhana Soudha, High Court, and Victorian statues.', 'Created in 1870 under Major General Richard Sankey, Cubbon Park is Bangalore’s central green haven. Shaded by towering bamboo groves, mahogany, and rain trees, it houses neo-classical red heritage buildings including the State Central Library (Seshadri Iyer Memorial Hall) and Attara Kacheri (High Court).', '{"Sprawling bamboo groves and flowerbeds right in the city center","Striking red neo-classical Victorian colonial monuments","Traffic-free weekend mornings perfect for walking and dog meetups"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Cubbon_Park_W.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cubbon_Park_W.jpg","photographer":"Wikimedia Commons / Augustus Binu/ facebook","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"blr-cubbon-park"}', '[]', 12.9757, 77.5929, '2 Hours', false, 0, 'Free entry', '6:00 AM – 8:00 PM Daily', '{"All Year Round"}', 4.8, '{"Nature Walk","Heritage Building Photography","Picnic in the Shade"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('blr-tipu-palace', 'Tipu Sultan''s Summer Palace', 'tipu-sultans-summer-palace', 'bengaluru-urban', 'Bengaluru Urban', '{"History","Heritage","Culture"}', '1791 ornate two-storey teakwood summer palace with fluted pillars and floral motifs, known as Rashk-e-Jannat.', 'Referred to by Tipu Sultan as the "Abode of Happiness and Envy of Heaven", this two-storey wooden mansion within Bangalore Fort is built entirely of French teakwood. Distinctive multi-tiered wooden arches and intricately painted floral motifs adorn the open balconies.', '{"Magnificent example of 18th-century Indo-Islamic teakwood construction","Museum displaying Tipu’s crowns, royal clothes, and Mysore rocket sketches","Peaceful oasis of historical tranquility in the heart of old Kalasipalyam"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/9/95/Tipu_Sultans_summer_palace_bangalore_frontview.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Tipu_Sultans_summer_palace_bangalore_frontview.jpg","photographer":"Wikimedia Commons / Pavithrah","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"blr-tipu-palace"}', '[]', 12.9593, 77.5738, '1 Hour', true, 20, '₹20 Indians, ₹250 Foreigners', '8:30 AM – 5:30 PM Daily', '{"All Year Round"}', 4.8, '{"Historical Tour","Wood Carving Appreciation","Museum Walk"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('bgk-badami-caves', 'Badami Rock-Cut Cave Temples', 'badami-cave-temples', 'bagalkote', 'Bagalkote (Badami & Pattadakal)', '{"Heritage","History","Culture","Photography"}', '6th-century rock-cut monolithic caves carved into red sandstone cliffs overlooking serene Agastya Lake.', 'Carved out of soft Badami sandstone cliffs by the early Chalukya kings in the 6th century, these four cave temples represent Hindu, Jain, and early iconography. Cave 1 features the renowned 18-armed dancing Nataraja carving in 81 distinct poses, while Cave 3 boasts majestic Vishnu avatars.', '{"Masterpiece 18-armed dancing Nataraja displaying 81 classical Bharatanatyam mudras","Stunning golden sandstone cliff reflections in ancient Agastya Lake","Iconic Bhootanatha temples perched on the eastern water’s edge"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/1/10/Badami-cave-temples.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Badami-cave-temples.JPG","photographer":"Wikimedia Commons / rajeshodayanchal","license":"CC BY 3.0","attribution":"Wikimedia Commons / CC BY 3.0","placeId":"bgk-badami-caves"}', '[]', 15.9187, 75.6766, '2.5 Hours', true, 25, '₹25 Indians, ₹300 Foreigners', '9:00 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Rock Cave Exploration","Agastya Lake Circuit Walk","Photography"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('bgk-pattadakal', 'Pattadakal UNESCO Group of Monuments', 'pattadakal-monuments', 'bagalkote', 'Bagalkote (Badami & Pattadakal)', '{"Heritage","History","Culture"}', 'UNESCO World Heritage coronation site of the Chalukyas showcasing a harmonious fusion of North and South Indian temple styles.', 'Pattadakal was the ceremonial coronation capital of the Chalukya dynasty along the Malaprabha River. The site features 10 major temples built side-by-side in the 7th and 8th centuries, representing an experimental laboratory where Northern Nagara shikhara towers stand adjacent to Southern Dravidian gopurams.', '{"UNESCO World Heritage Site with harmonious confluence of Nagara and Dravidian temples","Grand 8th-century Virupaksha Temple with Ramayana and Mahabharata stone friezes","Tranquil Malaprabha riverside monument setting"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/03/Pattadakal_000.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pattadakal_000.JPG","photographer":"Wikimedia Commons / Nithin bolar k","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"bgk-pattadakal"}', '[]', 15.9497, 75.8164, '2 Hours', true, 40, '₹40 Indians, ₹600 Foreigners', '9:00 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"UNESCO Heritage Tour","Sculptural Photography","Archaeological Exploration"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('bgk-aihole', 'Aihole (Cradle of Indian Temple Architecture)', 'aihole-cradle-of-architecture', 'bagalkote', 'Bagalkote (Badami & Pattadakal)', '{"Heritage","History","Culture"}', 'Historic archaeological open-air museum boasting over 120 stone temples built between the 4th and 12th centuries.', 'Regarded as the "Cradle of Indian Temple Architecture", Aihole served as an experimental architectural workshop for guild stone artisans. The distinctive apsidal Durga Temple with its pillared peristyle corridor resembles an ancient Buddhist chaitya hall executed in Hindu stone temple craft.', '{"Iconic apsidal horseshoe-shaped Durga Temple with exquisite pillar carvings","Over 120 historic experimental temples scattered across scenic village lanes","Megalithic dolmens and ancient rock-cut Ravana Phadi cave"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/b/b3/8th_century_Durga_temple_exterior_view%2C_Aihole_Hindu_temples_and_monuments_3.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:8th_century_Durga_temple_exterior_view,_Aihole_Hindu_temples_and_monuments_3.jpg","photographer":"Wikimedia Commons / Ms Sarah Welch","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"bgk-aihole"}', '[]', 16.0194, 75.8824, '2.5 Hours', true, 25, '₹25 Indians, ₹300 Foreigners', '9:00 AM – 5:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Temple Architecture Walk","Village Exploration","Archaeological Museum Tour"}', true, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('bgk-banashankari', 'Banashankari Devi Temple', 'banashankari-temple', 'bagalkote', 'Bagalkote (Badami & Pattadakal)', '{"Spiritual","Heritage","Culture"}', 'Ancient 7th-century Shakta shrine situated inside the holy Tilakaranya forest with a stepwell pond.', 'Dedicated to Goddess Parvati as Banashankari ("Goddess of the Forests"), this popular pilgrimage shrine sits along the Badami road. It features a sacred square stepped reservoir (Haridra Tirtha) surrounded on three sides by colonnaded stone cloisters and a multi-tiered watchtower.', '{"Revered Kuladevata temple for millions across Karnataka and Maharashtra","Picturesque stepped sacred lake (Haridra Tirtha) with stone pavilions","Atmospheric evening aarti and vibrant rural fair ground"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/3/35/Shakambari_temple_near_Badami.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shakambari_temple_near_Badami.JPG","photographer":"Wikimedia Commons / Nvvchar","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"bgk-banashankari"}', '[]', 15.8672, 75.7042, '1.5 Hours', false, 0, 'Free entry', '6:00 AM – 8:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Temple Darshan","Stepwell Photography","Local Village Interaction"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hsn-belur-temple', 'Belur Chennakeshava Temple', 'belur-chennakeshava-temple', 'hassan', 'Hassan (Belur & Halebidu)', '{"Heritage","History","Culture"}', '12th-century UNESCO World Heritage Hoysala masterpiece celebrated for its dancing Madanika bracket figures.', 'Commissioned by King Vishnuvardhana in 1117 CE to celebrate victory over the Cholas, this star-shaped soapstone temple took 103 years to complete. Its exterior walls and lintels feature 42 world-famous Madanika (bracket celestial nymph) carvings, each with jewel-like micro-carvings of fingernails, rings, and hairstyles.', '{"UNESCO World Heritage Sacred Ensembles of the Hoysalas","42 astonishing Madanika bracket figures with razor-sharp filigree details","Gravity-defying stone pillar (Deepa Stambha) balanced on its own center of gravity"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/0a/The_Courtyard_of_Chennakesava_Temple_-_Belur.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:The_Courtyard_of_Chennakesava_Temple_-_Belur.jpg","photographer":"Wikimedia Commons / Bikashrd","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hsn-belur-temple"}', '[]', 13.1624, 75.8596, '2.5 Hours', false, 0, 'Free entry', '7:30 AM – 7:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Temple Architecture Guided Tour","Madanika Sculptural Study","Photography"}', false, true, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hsn-halebidu-temple', 'Halebidu Hoysaleswara Temple', 'halebidu-hoysaleswara-temple', 'hassan', 'Hassan (Belur & Halebidu)', '{"Heritage","History","Culture"}', 'Twin-shrine UNESCO World Heritage Hoysala wonder with thousands of continuous narrative stone wall friezes.', 'The ancient capital of Dwarasamudra, Halebidu was the seat of the Hoysala Empire. The 12th-century twin-shrined Hoysaleswara temple features uninterrupted bands of soapstone friezes wrapping around its exterior base: 1,248 distinct elephants, lions, horses, makaras, and intricate depictions of Hindu epics.', '{"UNESCO World Heritage Site with unmatched depth of soapstone frieze work","No two relief carvings out of thousands are identical anywhere on the outer wall","Gigantic monolithic Nandi bull pavilions carved out of dark chloritic schist"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/0/0d/Hoysaleshwara_temple_in_Monsoon.JPG","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hoysaleshwara_temple_in_Monsoon.JPG","photographer":"Wikimedia Commons / Karthikbs23","license":"CC BY-SA 3.0","attribution":"Wikimedia Commons / CC BY-SA 3.0","placeId":"hsn-halebidu-temple"}', '[]', 13.2144, 75.9942, '2.5 Hours', false, 0, 'Free entry', '6:30 AM – 6:30 PM Daily', '{"October","November","December","January","February"}', 4.8, '{"Sculpture Exploration","Archaeological Museum Tour","Mythological Relief Study"}', false, true, NULL)
