INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hsn-shravanabelagola', 'Shravanabelagola Gommateshwara Monolith', 'shravanabelagola-gommateshwara', 'hassan', 'Hassan (Belur & Halebidu)', '{"Spiritual","Heritage","History","Viewpoints"}', 'World’s tallest monolithic free-standing statue (57 ft / 17 m) carved from a single granite hill peak in 981 CE.', 'Erected by Western Ganga dynasty commander Chavundaraya on Vindhyagiri hill, this 57-foot naked monolithic statue of Lord Bahubali (Gommateshwara) has stood in serene meditation for over a millennium. A climb of 650 stone steps cut into granite rewards visitors with deep spiritual peace.', '{"57-foot monolithic granite marvel standing free atop a sheer rocky ridge","One of the holiest Jain pilgrimage centers in the world","Venue for the grand Mahamastakabhisheka festival held once every 12 years"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/8/87/Gommateshwara%2C_Shravanabelagola.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Gommateshwara,_Shravanabelagola.jpg","photographer":"Wikimedia Commons / Kuldeep S","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hsn-shravanabelagola"}', '[]', 12.8572, 76.4856, '3 Hours', false, 0, 'Free entry (Socks recommended for heated rock)', '6:30 AM – 6:00 PM Daily', '{"October","November","December","January","February","March"}', 4.8, '{"Vindhyagiri Hill Step Climb","Statue Darshan","Ancient Kannada Inscriptions Tour"}', false, false, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, district_id = EXCLUDED.district_id;

INSERT INTO destinations (id, name, slug, district_id, district_name, categories, short_description, full_description, why_visit, image, gallery, latitude, longitude, visit_duration, entry_fee, entry_fee_amount, entry_fee_string, timings, best_months, rating, activities, is_hidden_gem, is_featured, accessibility_notes)
VALUES ('hsn-shettihalli-church', 'Shettihalli Submerged Rosary Church', 'shettihalli-rosary-church', 'hassan', 'Hassan (Belur & Halebidu)', '{"Heritage","Photography","Adventure"}', '1860 French Gothic church submerged every monsoon by the Hemavathi River reservoir waters.', 'Built by French missionaries in 1860 with mortar, bricks, and eggshells, this hauntingly beautiful Gothic church was deserted after the Gorur Dam on Hemavathi River was built in 1960. During monsoons, water submerges up to half the ruins, accessible only by coracles, while in summer visitors walk on dry cracked reservoir beds right into the arches.', '{"Surreal Gothic ruins emerging out of reservoir waters","Coracle boat ride right through the church nave during high water season","Iconic photography location with reflection of Gothic arches"}', '{"imageUrl":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Shettihalli_Church..jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shettihalli_Church..jpg","photographer":"Wikimedia Commons / Atulnain007","license":"CC BY-SA 4.0","attribution":"Wikimedia Commons / CC BY-SA 4.0","placeId":"hsn-shettihalli-church"}', '[]', 12.9184, 76.0469, '1.5 Hours', false, 0, 'Free entry', 'Open 24 hours (Best early morning or sunset)', '{"July to October (Submerged)","December to May (Dry bed)"}', 4.8, '{"Ruins Photography","Coracle Boating (Seasonal)","Sunset Watching"}', true, false, NULL)
